.seedContainer {
  margin-bottom: 1rem;
  text-align: center;
}

.seedButton {
  padding: 12px 24px;
  background: linear-gradient(135deg, #10b981, #059669);
  color: white;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-size: 14px;
  font-weight: 600;
  transition: all 0.2s ease;
  box-shadow: 0 2px 4px rgba(16, 185, 129, 0.2);
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 auto;
}

.seedButton:hover:not(:disabled) {
  background: linear-gradient(135deg, #059669, #047857);
  box-shadow: 0 4px 8px rgba(16, 185, 129, 0.3);
  transform: translateY(-1px);
}

.seedButton:disabled {
  opacity: 0.7;
  cursor: not-allowed;
  transform: none;
}

.spinner {
  width: 16px;
  height: 16px;
  border: 2px solid rgba(255, 255, 255, 0.3);
  border-top: 2px solid white;
  border-radius: 50%;
  animation: spin 1s linear infinite;
}

@keyframes spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

.result {
  margin-top: 12px;
  padding: 12px 16px;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 500;
}

.success {
  background: #d1fae5;
  color: #065f46;
  border: 1px solid #a7f3d0;
}

.error {
  background: #fee2e2;
  color: #991b1b;
  border: 1px solid #fecaca;
}

'use client';

import { useState } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { seedMockTodos } from '../../scripts/seedMockTodos';
import styles from './SeedButton.module.css';

const SeedButton = () => {
  const { user } = useAuth();
  const [isSeeding, setIsSeeding] = useState(false);
  const [seedResult, setSeedResult] = useState<string | null>(null);

  const handleSeed = async () => {
    if (!user) {
      setSeedResult('❌ Please sign in first');
      return;
    }

    try {
      setIsSeeding(true);
      setSeedResult(null);

      const results = await seedMockTodos(user.uid, 50);

      setSeedResult(`✅ Successfully created ${results.length} todos with random deadlines between 7 days ago and 7 days ahead!`);

      // Refresh the page after a short delay to show the new todos
      setTimeout(() => {
        window.location.reload();
      }, 2000);

    } catch (error) {
      console.error('Error seeding todos:', error);
      setSeedResult(`❌ Failed to seed todos: ${error instanceof Error ? error.message : 'Unknown error'}`);
    } finally {
      setIsSeeding(false);
    }
  };

  if (!user) {
    return null; // Don't show the button if user is not signed in
  }

  return (
    <div className={styles.seedContainer}>
      <button
        onClick={handleSeed}
        disabled={isSeeding}
        className={styles.seedButton}
      >
        {isSeeding ? (
          <>
            <span className={styles.spinner}></span>
            Seeding 50 todos...
          </>
        ) : (
          ' Seed 50 Sample Todos'
        )}
      </button>

      {seedResult && (
        <div className={`${styles.result} ${seedResult.startsWith('✅') ? styles.success : styles.error}`}>
          {seedResult}
        </div>
      )}
    </div>
  );
};

export default SeedButton;

